<?php

declare(strict_types=1);

namespace App\Controller;

use Cake\HttpFoundation\Response;

/**
 * Swagger Controller
 */
class SwaggerController extends AppController
{
    /**
     * This function serves OpenAPI YAML specification.
     *
     * @return \Cake\Http\Response
     */
    public function index(): Response
    {
        $swaggerPath = WWW_ROOT . '../openapi.yaml';

        if (!file_exists($swaggerPath)) {
            return $this->response->withStatus(404)->withStringBody("Swagger file not found.");
        }

        $yamlContent = file_get_contents($swaggerPath);
        return $this->response
            ->withType('yaml')
            ->withStringBody($yamlContent);
    }

    /**
     * Display Swagger UI on the endpoint.
     * 
     * @return \Cake\Http\Response
     */
    public function ui(): Response
    {
        return $this->redirect('https://editor.swagger.io/?url=' . urlencode('http://' . $_SERVER['HTTP_HOST'] . '/swagger'));
    }
}

