#[tokio::main]
async fn main() {
    env_logger::init();

    let mongo_uri = env::var("MONGO_URI").expect("MONGO_URI must be set");
    let db = db::init_db(&mongo_uri).await.expect("Failed to connect to MongoDB");

    let db_filter = warp::any().map(move || db.clone());

    let cors = warp::cors()
        .allow_any_origin()
        .allow_methods(vec!["GET", "POST", "PUT", "DELETE", "OPTIONS"])
        .allow_headers(vec!["Content-Type", "Authorization"]);

    // Auth routes
    let auth_routes = warp::path("api")
        .and(warp::path("auth"))
        .and(
            handlers::auth::login_route(db_filter.clone())
                .or(handlers::auth::register_route(db_filter.clone()))
        );

    // Service routes
    let service_routes = warp::path("api")
        .and(warp::path("services"))
        .and(
            handlers::services::list_services(db_filter.clone())
                .or(handlers::services::get_service(db_filter.clone()))
                .or(handlers::services::create_service(db_filter.clone()))
                .or(handlers::services::update_service(db_filter.clone()))
                .or(handlers::services::delete_service(db_filter.clone()))
        );

    // Incident routes
    let incident_routes = warp::path("api")
        .and(warp::path("incidents"))
        .and(
