                .or(handlers::incidents::get_incident(db_filter.clone()))
                .or(handlers::incidents::create_incident(db_filter.clone()))
                .or(handlers::incidents::update_incident(db_filter.clone()))
                .or(handlers::incidents::delete_incident(db_filter.clone()))
        );

    // User routes
    let user_routes = warp::path("api")
        .and(warp::path("users"))
        .and(
            handlers::users::list_users(db_filter.clone())
                .or(handlers::users::delete_user(db_filter.clone()))
        );

    // Swagger routes
    let swagger_spec = warp::path("swagger")
        .and(warp::get())
        .and(warp::fs::file("./openapi.yaml"));

