using Microsoft.EntityFrameworkCore;
using Microsoft.IdentityModel.Tokens;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using DevPortal.Data;
using DevPortal.Models;
using DevPortal.Models.DTOs;
using BCrypt.Net;

namespace DevPortal.Services;

public class AuthService : IAuthService
{
    private readonly AppDbContext _context;
    private readonly IConfiguration _configuration;

    public AuthService(AppDbContext context, IConfiguration configuration)
    {
        _context = context;
        _configuration = configuration;
    }

    public async Task<LoginResponse?> Login(LoginRequest request)
    {
        var user = await _context.Users.FirstOrDefaultAsync(u => u.Email == request.Email);

        if (user == null || !BCrypt.Net.BCrypt.Verify(request.Password, user.PasswordHash))
        {
            return null;
        }

        var token = GenerateToken(user);

        return new LoginResponse
        {
            Token = token,
            Email = user.Email,
            Role = user.Role
        };
    }

    public async Task<User?> Register(RegisterRequest request)
    {
        if (await _context.Users.AnyAsync(u => u.Email == request.Email))
        {
            return null;
        }

        var user = new User
        {
            Email = request.Email,
            PasswordHash = BCrypt.Net.BCrypt.HashPassword(request.Password),
            Role = request.Role,
            CreatedAt = DateTime.UtcNow
        };

        _context.Users.Add(user);
        await _context.SaveChangesAsync();

        return user;
    }

    public async Task SeedDefaultUsers()
    {
        if (!await _context.Users.AnyAsync())
        {
            var admin = new User
            {
                Email = "admin@devportal.com",
                PasswordHash = BCrypt.Net.BCrypt.HashPassword(_configuration["DefaultAdminPassword"] ?? "Admin123!"),
                Role = "Admin",
                CreatedAt = DateTime.UtcNow
            };

            var developer = new User
            {
                Email = "dev@devportal.com",
                PasswordHash = BCrypt.Net.BCrypt.HashPassword(_configuration["DefaultDeveloperPassword"] ?? "Dev123!"),
                Role = "Developer",
                CreatedAt = DateTime.UtcNow
            };

            _context.Users.AddRange(admin, developer);
            await _context.SaveChangesAsync();
        }
    }

    public string GenerateToken(User user)
    {
        var jwtKey = _configuration["Jwt:Key"] ?? "DevPortalSecretKey123456789012345678901234567890";
        var key = Encoding.ASCII.GetBytes(jwtKey);
        var expiryHours = int.Parse(_configuration["Jwt:ExpiryInHours"] ?? "24");

        var tokenDescriptor = new SecurityTokenDescriptor
        {
            Subject = new ClaimsIdentity(new[]
            {
                new Claim(ClaimTypes.NameIdentifier, user.Id.ToString()),
                new Claim(ClaimTypes.Email, user.Email),
                new Claim(ClaimTypes.Role, user.Role)
            }),
            Expires = DateTime.UtcNow.AddHours(expiryHours),
            SigningCredentials = new SigningCredentials(new SymmetricSecurityKey(key), SecurityAlgorithms.HmacSha256Signature)
        };

        var tokenHandler = new JwtSecurityTokenHandler();
        var token = tokenHandler.CreateToken(tokenDescriptor);
        return tokenHandler.WriteToken(token);
    }
}

