    # Bypass auth for login and swagger routes
    if request.path in ("/auth/login", "/swagger", "/swagger-ui") or request.path.startswith("/swagger-ui/"):
        return await handler(request)

    auth_header = request.headers.get("Authorization", "")
    if not auth_header.startswith("Bearer "):
