class SiteController extends Controller
{
    /**
     * Directly serves the openapi.yaml file.
     * @return Response
     * @throws NotFoundHttpException
     */
    public function actionSwaggerYaml()
    {
        $filePath = Yii::getAlias('@webroot/swagger/openapi.yaml'); // Adjust this path if your outputDir is different

        if (!file_exists($filePath)) {
            throw new NotFoundHttpException('OpenAPI specification file not found.');
        }

        Yii::$app->response->format = Response::FORMAT_RAW;
        Yii::$app->response->headers->add('Content-Type', 'application/yaml');
        return file_get_contents($filePath);
    }

    /**
     * Redirects to the Swagger UI page.
     * @return Response
     */
    public function actionSwaggerHtml()
    {
        $allowedRedirects = ['/swagger/ui'];
        $url = Yii::$app->request->get('url');

        if (in_array($url, $allowedRedirects)) {
            return $this->redirect($url);
        } else {
            return $this->redirect('/'); // Redirect to a safe default URL
        }
    }
}

