    <span>Page {{page}}</span>
    <button ng-disabled="!hasMore" ng-click="nextPage()">Next</button>
  </div>

<script>
angular.module('atsApp', [])
  .controller('AdminCtrl', ['$scope', '$http', function($scope, $http) {
    $scope.loginData = {};
    $scope.authToken = null;
    $scope.candidates = [];
    $scope.page = 1;
    $scope.pageSize = 10;
    $scope.hasMore = false;
    $scope.search = '';
    $scope.statusFilter = '';

    $scope.login = function() {
      $http.post('/api/login', $scope.loginData)
        .then(function(res) {
          $scope.authToken = res.data.token;
          $scope.loginError = null;
          $scope.loadCandidates();
        }, function(err) {
          $scope.loginError = 'Invalid credentials';
        });
    };

    $scope.loadCandidates = function() {
      const params = {
        page: $scope.page,
        page_size: $scope.pageSize,
        search: $scope.search,
        status: $scope.statusFilter
      };
      $http.get('/api/candidates', {
        headers: { Authorization: 'Bearer ' + $scope.authToken },
        params: params
      }).then(function(res) {
        $scope.candidates = res.data.candidates;
        $scope.hasMore = (res.data.candidates.length === $scope.pageSize);
      });
    };

    $scope.nextPage = function() {
      $scope.page += 1;
      $scope.loadCandidates();
    };
    $scope.prevPage = function() {
      if ($scope.page > 1) {
        $scope.page -= 1;
        $scope.loadCandidates();
      }
    };
  }]);
</script>
