              this.total = data.total
              this.limit = data.limit
              this.page = data.page
              this.categories = [...new Set(data.deals.map(d => d.category))]
            })
            .catch(err => console.error(err))
        },
        nextPage() {
          if (this.page < this.totalPages) {
            this.page++
            this.fetchDeals()
          }
        },
        prevPage() {
          if (this.page > 1) {
            this.page--
            this.fetchDeals()
          }
        }
