      data() {
        return {
          token: localStorage.getItem('jwt') || '',
          habits: [],
          loginEmail: '',
          loginPassword: '',
          newHabit: { name: '', description: '' }
        }
      },
      methods: {
        setAuthHeader() {
          axios.defaults.headers.common['Authorization'] = `Bearer ${this.token}`
        },
        login() {
          axios.post('/auth/login', {
            email: this.loginEmail,
            password: this.loginPassword
          }).then(res => {
            this.token = res.data.token
            localStorage.setItem('jwt', this.token)
            this.setAuthHeader()
            this.fetchHabits()
          }).catch(err => alert('Login failed'))
        },
        logout() {
          this.token = ''
          localStorage.removeItem('jwt')
          delete axios.defaults.headers.common['Authorization']
          this.habits = []
        },
        fetchHabits() {
          axios.get('/habits').then(res => {
            this.habits = res.data
          })
        },
        addHabit() {
          axios.post('/habits', { habit: this.newHabit }).then(res => {
            this.habits.push(res.data)
            this.newHabit = { name: '', description: '' }
          })
        },
        toggleCompleted(habit) {
          axios.patch(`/habits/${habit.id}`, { habit: { completed: habit.completed } })
        },
        deleteHabit(id) {
          axios.delete(`/habits/${id}`).then(() => {
            this.habits = this.habits.filter(h => h.id !== id)
          })
        }
      },
      mounted() {
        if (this.token) {
          this.setAuthHeader()
          this.fetchHabits()
        }
      }
    }).mount('#app')
  </script>
