from flask import Blueprint, request, jsonify
from flask_jwt_extended import jwt_required
from models import get_db

items_bp = Blueprint('items', __name__)

@items_bp.route('', methods=['GET'])
@jwt_required()
def get_items():
    db = get_db()
    cur = db.execute('SELECT * FROM items')
    items = cur.fetchall()
    return jsonify([dict(item) for item in items]), 200

@items_bp.route('', methods=['POST'])
@jwt_required()
def create_item():
    data = request.get_json()
    name = data.get('name')
    description = data.get('description', '')
    price = data.get('price')
    if not name or price is None:
        return jsonify({'msg': 'Name and price are required'}), 400
    db = get_db()
    db.execute(
        'INSERT INTO items (name, description, price) VALUES (?, ?, ?)',
        (name, description, price)
    )
    db.commit()
    return jsonify({'msg': 'Item created'}), 201

@items_bp.route('/<int:item_id>', methods=['GET'])
@jwt_required()
def get_item(item_id):
    db = get_db()
    cur = db.execute('SELECT * FROM items WHERE id = ?', (item_id,))
    item = cur.fetchone()
    if item:
        return jsonify(dict(item)), 200
    return jsonify({'msg': 'Item not found'}), 404

@items_bp.route('/<int:item_id>', methods=['PUT'])
@jwt_required()
def update_item(item_id):
    data = request.get_json()
    name = data.get('name')
    description = data.get('description', '')
    price = data.get('price')
    db = get_db()
    cur = db.execute('SELECT * FROM items WHERE id = ?', (item_id,))
    if not cur.fetchone():
        return jsonify({'msg': 'Item not found'}), 404
    db.execute(
        'UPDATE items SET name = ?, description = ?, price = ? WHERE id = ?',
        (name, description, price, item_id)
    )
    db.commit()
    return jsonify({'msg': 'Item updated'}), 200

@items_bp.route('/<int:item_id>', methods=['DELETE'])
@jwt_required()
def delete_item(item_id):
    db = get_db()
    cur = db.execute('SELECT * FROM items WHERE id = ?', (item_id,))
    if not cur.fetchone():
        return jsonify({'msg': 'Item not found'}), 404
    db.execute('DELETE FROM items WHERE id = ?', (item_id,))
    db.commit()
    return jsonify({'msg': 'Item deleted'}), 200

from aiohttp import web
import os
import secrets

# Simple token-based authentication
# In a real app, you'd use JWT or OAuth
API_TOKENS = {
    "user1": os.environ.get("API_TOKEN_USER1", "")
}

async def auth_middleware(app: web.Application, handler):
    async def middleware_handler(request):
        # Skip auth for swagger
        if request.path.startswith('/swagger') or request.path == '/':
            return await handler(request)

        auth_header = request.headers.get('Authorization')
        if not auth_header or not auth_header.startswith('Bearer '):
            return web.json_response({'error': 'Missing or invalid authorization header'}, status=401)

        token = auth_header.split(' ')[1]
        user_id = None

        for uid, api_token in API_TOKENS.items():
            if secrets.compare_digest(token, api_token):
                user_id = uid
                break

        if not user_id:
            return web.json_response({'error': 'Invalid token'}, status=401)

        request['user_id'] = user_id
        return await handler(request)

    return middleware_handler

def setup_auth(app: web.Application):
    app.middlewares.append(auth_middleware)

