<div id="app"></div>
<script type="text/babel">
const { useState } = React;

function App() {
  const [token, setToken] = useState('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [gistTitle, setGistTitle] = useState('');
  const [gistContent, setGistContent] = useState('');
  const [gists, setGists] = useState([]);

  const login = async () => {
    const res = await fetch('/login', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({username, password})
    });
    if(res.ok){
      const data = await res.json();
      setToken(data.token);
    } else {
      alert('Login failed');
    }
  };

  const fetchGists = async () => {
    const res = await fetch('/graphql', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      },
      body: JSON.stringify({query: '{ gists { title content } }'})
    });
    const data = await res.json();
    setGists(data.data.gists);
  };

  const createGist = async () => {
    const res = await fetch('/graphql', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      },
      body: JSON.stringify({
        query: \`
          mutation CreateGist($title: String!, $content: String!) {
            create_gist(title: $title, content: $content) {
              gist { id title content }
            }
          }
        \`,
        variables: { title: gistTitle, content: gistContent }
      })
    });
    const data = await res.json();
    console.log(data);
    fetchGists();
  };

  return (
    <div>
      {!token && (
        <div>
          <h2>Login</h2>
          <input placeholder="username" value={username} onChange={e=>setUsername(e.target.value)}/>
          <input placeholder="password" type="password" value={password} onChange={e=>setPassword(e.target.value)}/>
          <button onClick={login}>Login</button>
        </div>
      )}
      {token && (
        <div>
          <h2>Create Gist</h2>
          <input placeholder="Title" value={gistTitle} onChange={e=>setGistTitle(e.target.value)}/>
          <br/>
          <textarea placeholder="Content" value={gistContent} onChange={e=>setGistContent(e.target.value)}/>
          <br/>
          <button onClick={createGist}>Create</button>
          <h3>Your Gists</h3>
          <button onClick={fetchGists}>Refresh</button>
          <ul>
            {gists.map((g, i)=>(<li key={i}>{g.title}: {g.content}</li>))}
          </ul>
        </div>
      )}
    </div>
  );
}

